{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C27"],
      "claim": "Flupirtine, a small oral drug with fluorophenyl and amide/ester-like polar functionality, showed 90% absolute oral bioavailability in healthy volunteers, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Lemborexant, a fused heterocyclic drug with fluorophenyl substitution, was at least 87% bioavailable after oral dosing in healthy subjects, supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Trovafloxacin, a fused heterocyclic fluoroaryl drug, had 88% absolute oral bioavailability in humans, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Melperone, a fluorophenyl-containing small molecule, showed 64 ± 16.6% absolute oral bioavailability in healthy volunteers, supporting F above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Risperidone, a fused heterocyclic drug, has 70% absolute oral bioavailability in humans, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "One low-bioavailability analogue showed ~10% or less oral bioavailability in healthy subjects, but its much larger, more hydrogen-bond-donating structure limits transfer to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "Most transferable experimental evidence points to moderate-to-high oral bioavailability (50–90%) for small, lipophilic, fluorophenyl-containing drugs, and the query is a compact ester-amide fused heterocycle with no obvious absorption-limiting features. The single low-bioavailability analogue is structurally more distant and less transferable. Overall, F ≥ 20% is better supported, though confidence is low because all Morgan similarities are below 0.26.",
  "evidence_gaps": [
    "No direct experimental bioavailability data exist for the exact query scaffold.",
    "All retrieved analogues have low Morgan similarity (<0.26), limiting structural transferability.",
    "The query contains an ethyl ester that may undergo presystemic hydrolysis, but this is not directly evidenced by the retrieved records."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

